import {FlappyEnv} from './engine.js';
import {policyAction,AGENT_CONFIG} from './agent.js';
import {loadLearningLab} from './lab.js';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
let difficulty='classic',env=new FlappyEnv(),mode='ready',sound=false,inspect=false,queued=false,last=0,accumulator=0,best={},history=[],run=0,audio;
let pilot='human',lab,agentContext,agentRate=4,journeyTimer;
try{best=JSON.parse(localStorage.getItem('flappy-lab-best')||'{}')||{};}catch{}
function updateBest(){ $('best').textContent=String(best[difficulty]||0).padStart(2,'0'); }
function tone(frequency,duration=.08,type='sine',volume=.035){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(frequency,audio.currentTime);o.frequency.exponentialRampToValueAtTime(frequency*.6,audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function overlay(label,title,text,button,hint){$('overlayLabel').textContent=label;$('overlayTitle').textContent=title;$('overlayText').innerHTML=text;$('start').innerHTML=button+' <span>↗</span>';$('overlayHint').innerHTML=hint;$('overlay').hidden=false;}
function fresh(){if(pilot==='agent'&&lab){prepareAgent(false);return;}env=new FlappyEnv({seed:Math.floor(Math.random()*4294967296),difficulty});mode='ready';queued=false;accumulator=0;last=0;overlay('THE SKY IS YOURS','Find your rhythm.','Keep your wings moving.<br>Find your way through the green.','Let’s fly','or press <kbd>space</kbd> to begin');$('status').textContent='READY TO FLY';$('pause').disabled=true;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause game');refresh();}
function flap(){if(mode==='paused')return;if(pilot==='agent'){if(mode==='ready'||mode==='over')prepareAgent(true);return;}if(mode==='ready'||mode==='over'){if(mode==='over')fresh();mode='playing';$('overlay').hidden=true;$('status').textContent='IN FLIGHT';$('pause').disabled=false;$('announcement').textContent='Flight started.';last=0;accumulator=0;}queued=true;canvas.focus({preventScroll:true});}
function pause(){if(mode==='playing'){mode='paused';queued=false;overlay('TAKE A BREATHER','Holding steady.','Your flight will be right here.','Resume flight','or press <kbd>P</kbd> to resume');$('status').textContent='PAUSED';$('pause').textContent='▷';$('pause').setAttribute('aria-label','Resume game');}else if(mode==='paused'){mode='playing';$('overlay').hidden=true;$('status').textContent='IN FLIGHT';$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause game');last=0;accumulator=0;}}
function end(){if(pilot==='agent'){endAgent();return;}mode='over';$('pause').disabled=true;$('status').textContent='FLIGHT COMPLETE';tone(120,.23,'triangle',.06);const record=env.score>(best[difficulty]||0);if(record){best[difficulty]=env.score;try{localStorage.setItem('flappy-lab-best',JSON.stringify(best));}catch{}updateBest();}run++;history.unshift({run,score:env.score,time:env.ticks/60,difficulty});history=history.slice(0,4);$('runCount').textContent=run;$('history').innerHTML=history.map(h=>`<div class="history-row"><span class="flight-num">${String(h.run).padStart(2,'0')}</span><div><strong>${h.difficulty==='classic'?'Classic':'Gentle'} skies</strong><small>${h.time.toFixed(1)}s in the air</small></div><b>${h.score} ${h.score===1?'pt':'pts'}</b></div>`).join('');overlay(record?'A NEW PERSONAL BEST':'EVERY FLIGHT TEACHES YOU',record?'A new high.':'Back to the skies?',`${env.score} ${env.score===1?'pipe':'pipes'} cleared · ${(env.ticks/60).toFixed(1)} seconds aloft<br>${record?'That’s one for the flight log.':'A fresh start is just a flap away.'}`,'Fly again','or press <kbd>space</kbd> to try again');$('announcement').textContent=`Flight complete. Score ${env.score}. ${record?'New personal best.':''}`;}
function refresh(){const o=env.observe();$('score').textContent=String(env.score).padStart(2,'0');$('airtime').innerHTML=(env.ticks/60).toFixed(1)+'<span>s</span>';$('flaps').textContent=env.flaps;$('height').textContent=o.birdY.toFixed(2);$('velocity').textContent=o.velocity.toFixed(2);$('distance').textContent=o.pipeDistance.toFixed(2);$('gap').textContent=o.gapTop.toFixed(2)+' / '+o.gapBottom.toFixed(2);}
function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}}
function cloud(x,y,s=1){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#eff5e6';ctx.beginPath();ctx.moveTo(-38,10);ctx.bezierCurveTo(-50,-9,-25,-18,-15,-9);ctx.bezierCurveTo(-12,-38,25,-34,27,-13);ctx.bezierCurveTo(53,-19,62,9,43,12);ctx.closePath();ctx.fill();ctx.restore();}
function bird(x,y,time){ctx.save();ctx.translate(x,y);ctx.rotate(mode==='playing'?Math.max(-.35,Math.min(1.2,env.velocity*.075)):-.10);ctx.lineWidth=2.2;ctx.strokeStyle='#5b6447';ctx.fillStyle='#efbc51';ctx.beginPath();ctx.ellipse(0,0,19,15,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#f7d987';ctx.beginPath();ctx.ellipse(-3,6,12,7,0,0,Math.PI);ctx.fill();rounded(-19,Math.sin(time*.02)*2-1,17,11,5,'#d99f40','#5b6447');rounded(7,-12,12,14,5,'#fffcdf','#5b6447');rounded(14,-8,4,6,1,'#354a3b');rounded(12,2,17,7,2,'#e38549','#5b6447');ctx.fillStyle='#f6d47f';ctx.fillRect(-11,-12,9,3);ctx.restore();}
function draw(t){const c=env.config,w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,440);sky.addColorStop(0,'#dcead9');sky.addColorStop(1,'#eef2d8');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
  // A quiet, hand-drawn landscape. Rendering never changes the simulation.
  ctx.fillStyle='#eff0cd';ctx.beginPath();ctx.arc(741,91,36,0,Math.PI*2);ctx.fill();cloud(102,73,.82);cloud(398,110,.6);cloud(812,164,.73);cloud(602,47,.4);
  ctx.fillStyle='#d9e4ce';ctx.beginPath();ctx.moveTo(0,352);ctx.bezierCurveTo(170,243,226,375,385,321);ctx.bezierCurveTo(545,261,605,351,734,315);ctx.bezierCurveTo(811,278,877,313,900,293);ctx.lineTo(900,445);ctx.lineTo(0,445);ctx.fill();
  ctx.fillStyle='#d0dfc2';for(let i=0;i<19;i++){const x=i*55-12,hh=28+((i*13)%38);ctx.fillRect(x,405-hh,36,hh);ctx.fillRect(x+6,398-hh,24,8);ctx.fillStyle='#dce7cf';ctx.fillRect(x+9,414-hh,5,7);ctx.fillRect(x+22,414-hh,5,7);ctx.fillStyle='#d0dfc2';}
  ctx.fillStyle='#bfd3ac';ctx.beginPath();ctx.moveTo(0,430);for(let x=0;x<=925;x+=35){ctx.quadraticCurveTo(x-17,393-(x%57)/3,x,430);}ctx.lineTo(900,445);ctx.lineTo(0,445);ctx.fill();
  for(const p of env.pipes){const x=p.x,bottom=p.top+c.gap;const grad=ctx.createLinearGradient(x,0,x+c.pipeWidth,0);grad.addColorStop(0,'#7d9d6b');grad.addColorStop(.2,'#a2bd81');grad.addColorStop(.65,'#9ab77d');grad.addColorStop(1,'#688a5b');rounded(x, -20,c.pipeWidth,p.top+20,3,grad,'#5e7e53');rounded(x,bottom,c.pipeWidth,c.ground-bottom+10,3,grad,'#5e7e53');rounded(x-5,p.top-23,c.pipeWidth+10,23,3,'#94b277','#5e7e53');rounded(x-5,bottom,c.pipeWidth+10,23,3,'#94b277','#5e7e53');ctx.fillStyle='#bdd49b';ctx.fillRect(x+1,p.top-19,c.pipeWidth-2,3);ctx.fillRect(x+1,bottom+4,c.pipeWidth-2,3);ctx.fillStyle='#b7cf9255';ctx.fillRect(x+7,0,5,p.top-24);ctx.fillRect(x+7,bottom+25,5,c.ground-bottom-25);}
  ctx.fillStyle='#8fa97a';ctx.fillRect(0,c.ground,w,4);ctx.fillStyle='#b5c990';ctx.fillRect(0,c.ground+4,w,9);ctx.fillStyle='#dce3b9';ctx.fillRect(0,c.ground+13,w,h);ctx.fillStyle='#c6d2a3';for(let i=0;i<45;i++){const x=(i*27-env.ticks*c.speed)%930;ctx.fillRect(x,c.ground+18+(i%3)*10,3,2);}ctx.strokeStyle='#9cb587';ctx.lineWidth=1;for(let i=0;i<90;i++){const x=i*12;ctx.beginPath();ctx.moveTo(x,c.ground+4);ctx.lineTo(x+5,c.ground+10);ctx.stroke();}
  const y=mode==='ready'?222+Math.sin(t*.003)*5:env.y;bird(c.birdX,y,t);
  if(inspect){const p=env.nextPipe();ctx.setLineDash([5,5]);ctx.strokeStyle='#d87c46';ctx.lineWidth=1;ctx.beginPath();ctx.arc(c.birdX,y,c.radius,0,Math.PI*2);ctx.stroke();ctx.strokeRect(p.x,p.top,c.pipeWidth,c.gap);ctx.beginPath();ctx.moveTo(c.birdX,y);ctx.lineTo(p.x,p.top+c.gap/2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#526c50';ctx.font='10px monospace';ctx.fillText('TARGET GAP',p.x+2,p.top+c.gap/2-9);}
}
function frame(t){if(!last)last=t;const elapsed=Math.min(t-last,100);last=t;if(mode==='playing'){accumulator+=elapsed*(pilot==='agent'?agentRate:1);let stepped=false;while(accumulator>=1000/60&&mode==='playing'){const previous=env.score;const action=pilot==='agent'?(env.ticks%AGENT_CONFIG.decisionFrames===0?policyAction(env,agentContext.checkpoint.q):0):(queued?1:0);queued=false;env.step(action);if(action&&(pilot==='human'||agentRate<=2))tone(520);if(env.score>previous){tone(950,.12,'sine',.05);$('toast').textContent='+1 · Nicely flown';$('toast').classList.add('show');clearTimeout(frame.toastTimer);frame.toastTimer=setTimeout(()=>$('toast').classList.remove('show'),900);}accumulator-=1000/60;stepped=true;if(env.done||(pilot==='agent'&&(env.score>=agentContext.report.test.maxScore||env.ticks>=agentContext.report.test.maxTicks)))end();}if(stepped)refresh();}draw(t);requestAnimationFrame(frame);}
$('start').addEventListener('click',()=>mode==='paused'?pause():flap());canvas.addEventListener('pointerdown',e=>{e.preventDefault();flap();});$('pause').addEventListener('click',pause);$('restart').addEventListener('click',()=>{if(mode==='playing'||mode==='paused'){fresh();flap();}else fresh();});$('sound').addEventListener('click',()=>{sound=!sound;$('sound').innerHTML='♪<span>Sound '+(sound?'on':'off')+'</span>';$('sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');$('sound').title=sound?'Mute sound':'Enable sound';tone(650);});$('inspect').addEventListener('change',e=>{inspect=e.target.checked;$('telemetry').hidden=!inspect;});$('difficulty').addEventListener('change',e=>{difficulty=e.target.value;$('difficultyHelp').textContent=difficulty==='classic'?'The original challenge. Mind the gap.':'Wider openings. A little room to learn.';updateBest();fresh();});
window.addEventListener('keydown',e=>{if(['SELECT','INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.target.closest('button')&&['Space','Enter'].includes(e.code))return;if(['Space','ArrowUp','KeyW'].includes(e.code)){e.preventDefault();if(!e.repeat){if(mode==='paused')pause();else flap();}}if(e.code==='KeyP'&&!e.repeat){e.preventDefault();pause();}if(e.code==='KeyR'&&!e.repeat){e.preventDefault();fresh();flap();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='playing')pause();});window.addEventListener('blur',()=>{if(mode==='playing')pause();});
// The next ML phase can import FlappyEnv directly, or use this isolated browser API.
// Independent environments avoid racing the human player's animation loop.
window.flappyLab=Object.freeze({createEnv:options=>new FlappyEnv(options),getState:()=>({mode,pilot,checkpoint:pilot==='agent'?agentContext?.checkpoint.episode:null,difficulty,...env.info(),observation:env.observe()}),pause:()=>{if(mode==='playing')pause();}});
updateBest();refresh();requestAnimationFrame(frame);

function prepareAgent(autoplay){clearTimeout(journeyTimer);agentContext=lab.context();agentRate=agentContext.speed;difficulty='classic';env=new FlappyEnv({seed:agentContext.seed});queued=false;last=0;accumulator=0;mode=autoplay?'playing':'ready';const cp=agentContext.checkpoint,test=agentContext.report.test.results.find(r=>r.episode===cp.episode);$('bestLabel').textContent='TEST AVERAGE';$('best').textContent=test.meanScore.toFixed(2);$('status').textContent=autoplay?'AGENT IN FLIGHT':'AGENT READY';$('pause').disabled=!autoplay;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause game');$('difficulty').value='classic';$('difficulty').disabled=true;$('difficultyHelp').textContent='Classic rules, identical to training.';overlay(cp.episode===0?'BEFORE THE FIRST LESSON':'SAVED TRAINING CHECKPOINT',cp.episode===0?'Meet the beginner.':`${cp.episode.toLocaleString()} games later.`,`Course ${agentContext.course+1} · same game, learned decisions<br>Press play to see this policy in action.`,'Play sample','<kbd>P</kbd> pause · <kbd>R</kbd> replay');$('overlay').hidden=autoplay;document.querySelector('.game-footer').firstElementChild.textContent=`Agent / ${cp.episode.toLocaleString()} training games / Course ${agentContext.course+1} / ${agentRate}x`;refresh();if(autoplay)$('stage').scrollIntoView({behavior:'smooth',block:'center'});}
function endAgent(){mode='over';$('pause').disabled=true;const capped=!env.done;$('status').textContent=capped?'30-PIPE LIMIT REACHED':'SAMPLE COMPLETE';const cp=agentContext.checkpoint;overlay(capped?'THE EVALUATION LIMIT':'A REAL CHECKPOINT RUN',capped?'Thirty pipes. Still flying.':`${env.score} ${env.score===1?'pipe':'pipes'} cleared.`,`${cp.episode.toLocaleString()} training games · ${(env.ticks/60).toFixed(1)}s aloft<br>${capped?'Stopped at the shared 30-pipe limit.':'This policy still has room to learn.'}`,'Replay sample',agentContext.journey?'The next checkpoint starts shortly.':'Choose another checkpoint or course above.');$('announcement').textContent=`Checkpoint ${cp.episode}. ${env.score} pipes cleared.${capped?' Evaluation limit reached.':''}`;if(agentContext.journey)journeyTimer=setTimeout(()=>{if(pilot==='agent'&&!document.hidden){if(!lab.next())$('overlayHint').textContent='Journey complete. Replay any checkpoint above.';}},1400);}
function setPilot(value){if(value==='agent'&&!lab)return;clearTimeout(journeyTimer);pilot=value;lab?.stop();$('learningLab').hidden=value!=='agent';$('agentMode').classList.toggle('active',value==='agent');$('humanMode').classList.toggle('active',value==='human');$('agentMode').setAttribute('aria-pressed',String(value==='agent'));$('humanMode').setAttribute('aria-pressed',String(value==='human'));document.querySelector('.mode-badge strong').textContent=value==='agent'?'The agent is the pilot':'You’re the pilot';document.querySelector('.mode-badge small').textContent=value==='agent'?'Saved Q-learning policies':'Human mode · Your turn to fly';const foot=document.querySelector('.game-footer');foot.classList.toggle('agent-footer',value==='agent');foot.firstElementChild.innerHTML=value==='agent'?'Live policy playback · Classic skies · Fixed seed':'<kbd>Space</kbd><span>or</span><kbd>↑</kbd><span>to flap</span><span class="divider">/</span><span>Click or tap anywhere</span>';if(value==='agent')prepareAgent(false);else{$('difficulty').disabled=false;$('bestLabel').innerHTML='PERSONAL BEST <span class="star">✦</span>';$('difficultyHelp').textContent='The original challenge. Mind the gap.';$('labStatus').textContent='Your turn. Same rules, human intuition.';updateBest();fresh();}}
$('agentMode').addEventListener('click',()=>setPilot('agent'));$('humanMode').addEventListener('click',()=>setPilot('human'));
loadLearningLab((context,autoplay)=>{agentRate=context.speed;if(autoplay!==null){if(pilot!=='agent')setPilot('agent');prepareAgent(autoplay);}}).then(controller=>{lab=controller;setPilot('agent');document.querySelector('.next-note').innerHTML='<div class="next-icon">✳</div><div><span>LEARNED FROM EXPERIENCE</span><p>50,000 games of trial and error.<br>Five milestones you can watch.</p></div>';document.querySelector('.engine-note').innerHTML='<span class="green-dot"></span>Q-learning · 50,000 training games';}).catch(error=>{$('labLoading').textContent=error.message+' You can still fly yourself using the button above.';$('labStatus').textContent='Training data unavailable';});
